          <p className="text-gray-500 text-lg">Bạn chưa có đơn phản ánh nào.</p>
          <a href="#/report" className="text-indigo-600 font-bold hover:underline">Gửi đơn ngay →</a>
        </div>
      ) : (
        <div className="grid gap-6">
          {reports.map((report) => (
            <div key={report.id} className="bg-white rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all overflow-hidden group">
              <div className="p-6">
                <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
                  <div className="flex items-center gap-3">
                    <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getStatusColor(report.status)}`}>
                      {report.status}
                    </span>
                    <span className="text-xs text-gray-400 flex items-center gap-1">
                      <Clock size={12} />
                      {new Date(report.createdAt).toLocaleDateString('vi-VN')}
                    </span>
                  </div>
                  <span className="text-xs font-mono text-gray-400">ID: #{report.id.toUpperCase()}</span>
                </div>

                <h3 className="text-xl font-bold mb-2 group-hover:text-indigo-600 transition-colors">{report.title}</h3>
                <p className="text-gray-500 text-sm line-clamp-2 mb-4">{report.description}</p>

                <div className="flex items-center justify-between pt-4 border-t border-gray-50">
                  <div className="flex items-center gap-4">
                    <div className="text-xs">
                      <p className="text-gray-400 uppercase font-semibold">Loại hình</p>
                      <p className="font-medium">{report.type}</p>
                    </div>
                    <div className="text-xs">
                      <p className="text-gray-400 uppercase font-semibold">Minh chứng</p>
                      <p className="font-medium">{report.evidenceCount} tệp đính kèm</p>
                    </div>
                  </div>
                  <button className="flex items-center gap-2 text-indigo-600 font-bold text-sm hover:gap-3 transition-all">
