                    <ArrowRight size={16} />
                  </button>
                </div>
              </div>

              {report.aiSummary && (
                <div className="bg-indigo-50/50 p-4 border-t border-indigo-100/50">
                  <p className="text-xs text-indigo-800 flex gap-2">
                    <span className="bg-indigo-200 text-indigo-900 px-1.5 py-0.5 rounded font-bold uppercase text-[9px]">AI Summary</span>
                    {report.aiSummary.split('\n')[0]}...
                  </p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

