import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Send, CheckCircle2, User, Phone, MapPin, Calendar, Mail, FileText, AlertCircle, Info } from 'lucide-react';
import { ReportTargetType, ReportStatus, VULNERABLE_GROUPS, PUBLIC_INTEREST_GROUPS, Report } from '../types';
import { analyzeReport } from '../services/geminiService';

export const ReportForm: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [formData, setFormData] = useState<Partial<Report>>({
    targetType: ReportTargetType.VULNERABLE,
    reporterRole: 'Bản thân',
    subCategory: VULNERABLE_GROUPS[0],
    citizenName: '',
    birthYear: '',
    address: '',
    phoneNumber: '',
    email: '',
    title: '',
    description: '',
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const aiSummary = await analyzeReport({
        title: formData.title,
        description: `Loại: ${formData.targetType}. Đối tượng: ${formData.subCategory}. Nội dung: ${formData.description}`
      } as any);

      const newReport: Report = {
        ...formData as any,
        id: Math.random().toString(36).substr(2, 9),
        status: ReportStatus.PENDING,
        createdAt: new Date().toISOString(),
        aiSummary: aiSummary,
      };

      const existing = JSON.parse(localStorage.getItem('reports') || '[]');
      localStorage.setItem('reports', JSON.stringify([newReport, ...existing]));

      setSubmitted(true);
      setTimeout(() => navigate('/my-reports'), 2000);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-6 text-center">
        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center">
          <CheckCircle2 size={48} className="text-green-600" />
