        <p className="text-gray-500 max-w-md">Thông tin phản ánh đã được gửi đến Viện kiểm sát để xem xét khởi kiện/tham gia tố tụng bảo vệ lợi ích hợp pháp.</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-20">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-black text-gray-900 uppercase">Nội dung phản ánh</h1>
        <div className="h-1 w-20 bg-red-600 mx-auto mt-2 rounded-full" />
