            <div className="grid md:grid-cols-2 gap-4">
              <button
                type="button"
                onClick={() => setFormData({ ...formData, targetType: ReportTargetType.VULNERABLE, subCategory: VULNERABLE_GROUPS[0] })}
                className={`p-4 rounded-2xl border-2 text-left transition-all ${formData.targetType === ReportTargetType.VULNERABLE ? 'border-red-600 bg-red-50' : 'border-gray-100 bg-white'}`}
              >
                <div className="font-bold text-gray-900">Nhóm dễ bị tổn thương</div>
                <div className="text-xs text-gray-500">Trẻ em, người già, người khuyết tật...</div>
