              >
                <div className="font-bold text-gray-900">Nhóm lợi ích công</div>
                <div className="text-xs text-gray-500">Đất đai, môi trường, an toàn thực phẩm...</div>
              </button>
            </div>
          </div>

          {formData.targetType === ReportTargetType.VULNERABLE && (
            <div className="space-y-6 pt-4 animate-in fade-in duration-300">
              <div className="space-y-4">
                <label className="block text-sm font-bold text-gray-700">Bạn là ai?</label>
                <div className="flex gap-4">
                  <label className="flex-1 flex items-center gap-2 p-3 border rounded-xl cursor-pointer hover:bg-gray-50">
