import React, { useState } from 'react';

export const Logo: React.FC<{ size?: number; className?: string }> = ({ size = 48, className = "" }) => {
  // Danh sách các URL ảnh logo ngành Kiểm sát từ các nguồn khác nhau để dự phòng
  const logoSources = [
    "https://vksndtc.gov.vn/static/images/logo.png",
    "https://vks.vinhphuc.gov.vn/PublishingImages/LogoVKSND.png",
    "https://vks.hanam.gov.vn/vks/PublishingImages/logo_vks.png",
    "https://upload.wikimedia.org/wikipedia/vi/e/e0/Huy_hi%E1%BB%87u_Vi%E1%BB%87n_ki%E1%BB%83m_s%C3%A1t_nh%C3%A2n_d%C3%A2n_Vi%E1%BB%87t_Nam.svg"
  ];

  const [currentSrcIndex, setCurrentSrcIndex] = useState(0);
  const [hasError, setHasError] = useState(false);

  const handleError = () => {
    if (currentSrcIndex < logoSources.length - 1) {
      setCurrentSrcIndex(prev => prev + 1);
    } else {
      setHasError(true);
    }
  };

  return (
    <div 
      className={`flex items-center justify-center transition-all duration-500 hover:scale-105 ${className}`} 
      style={{ width: size, height: size }}
    >
      {!hasError ? (
        <img 
          src={logoSources[currentSrcIndex]}
          alt="Phù hiệu Viện kiểm sát nhân dân" 
          className="w-full h-full object-contain filter drop-shadow-[0_2px_4px_rgba(0,0,0,0.2)]"
          crossOrigin="anonymous"
          onError={handleError}
        />
      ) : (
        // Fallback cuối cùng nếu tất cả các link đều lỗi: Một biểu tượng hình khiên trang trọng
        <div 
          className="w-full h-full bg-red-700 rounded-full border-4 border-yellow-500 flex items-center justify-center shadow-lg"
          style={{ fontSize: size * 0.4 }}
        >
          <span className="text-yellow-400 font-black">VKS</span>
        </div>
      )}
    </div>
  );
};

