        </button>
      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Report, ReportStatus, ReportTargetType, Attachment } from '../types';
import { Scale, Users, FileCheck, AlertTriangle, MessageSquare, Eye, PieChart, TrendingUp, Filter, ChevronRight, CheckCircle, Paperclip, File, Image as ImageIcon, Film, Download, RefreshCcw } from 'lucide-react';
import { getAllReports, updateReportStatus as dbUpdateStatus } from '../services/storageService';

export const AdminDashboard = () => {
  const [reports, setReports] = useState<Report[]>([]);
  const [selectedReport, setSelectedReport] = useState<Report | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    setLoading(true);
    try {
      const data = await getAllReports();
      setReports(data);
    } catch (error) {
      console.error("Lỗi khi tải dữ liệu:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (reportId: string, newStatus: ReportStatus) => {
    try {
      await dbUpdateStatus(reportId, newStatus);
      const updatedReports = reports.map(report => 
        report.id === reportId ? { ...report, status: newStatus } : report
      );
      setReports(updatedReports);

      if (selectedReport && selectedReport.id === reportId) {
        setSelectedReport({ ...selectedReport, status: newStatus });
      }
    } catch (error) {
      alert("Không thể cập nhật trạng thái đơn.");
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (type: string) => {
    if (type.startsWith('image/')) return <ImageIcon size={16} className="text-blue-500" />;
    if (type.startsWith('video/')) return <Film size={16} className="text-purple-500" />;
    return <File size={16} className="text-gray-500" />;
  };

  const downloadFile = (file: Attachment) => {
    const link = document.createElement('a');
    link.href = file.data;
    link.download = file.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const stats = [
    { label: 'Chờ tiếp nhận', count: reports.filter(r => r.status === ReportStatus.PENDING).length, color: 'text-amber-600', bg: 'bg-amber-50', icon: <AlertTriangle size={20} /> },
    { label: 'Đang xử lý', count: reports.filter(r => r.status === ReportStatus.PROCESSING).length, color: 'text-blue-600', bg: 'bg-blue-50', icon: <TrendingUp size={20} /> },
    { label: 'Đã giải quyết', count: reports.filter(r => r.status === ReportStatus.RESOLVED).length, color: 'text-green-600', bg: 'bg-green-50', icon: <FileCheck size={20} /> },
    { label: 'Từ chối', count: reports.filter(r => r.status === ReportStatus.REJECTED).length, color: 'text-red-600', bg: 'bg-red-50', icon: <Scale size={20} /> },
  ];

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <RefreshCcw className="animate-spin text-red-700" size={32} />
        <p className="text-xs font-black uppercase text-gray-400">Đang tải dữ liệu từ hệ thống...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-black text-gray-900 uppercase tracking-tight">Hệ thống quản trị</h1>
        <p className="text-xs text-gray-500 font-medium">Lưu trữ IndexedDB (Không giới hạn dung lượng)</p>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="col-span-2 bg-red-900 text-white p-6 rounded-[2rem] shadow-xl flex items-center justify-between relative overflow-hidden">
          <div className="relative z-10">
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-red-200 mb-1">Tổng số đơn phản ánh</p>
            <p className="text-5xl font-black tracking-tighter">{reports.length}</p>
          </div>
          <div className="bg-white/10 p-4 rounded-3xl relative z-10">
            <PieChart size={40} className="text-red-200" />
          </div>
          <div className="absolute top-0 right-0 w-40 h-40 bg-white/5 rounded-full -mr-10 -mt-10" />
        </div>

        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm flex flex-col gap-3">
            <div className={`w-10 h-10 rounded-2xl ${stat.bg} flex items-center justify-center ${stat.color}`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-wider">{stat.label}</p>
              <p className="text-2xl font-black text-gray-900">{stat.count}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="space-y-4">
        <div className="flex items-center justify-between px-2">
          <h3 className="text-sm font-black text-gray-900 uppercase tracking-tight flex items-center gap-2">
            <Filter size={16} className="text-red-700" />
            Danh sách vụ việc
          </h3>
        </div>

        <div className="space-y-3">
          {reports.length === 0 ? (
            <div className="text-center py-10 bg-white rounded-3xl border border-dashed border-gray-200">
              <p className="text-xs text-gray-400 font-bold uppercase">Chưa có dữ liệu phản ánh</p>
            </div>
          ) : (
            reports.map((report) => (
              <div 
                key={report.id}
                onClick={() => setSelectedReport(report)}
                className={`bg-white p-4 rounded-2xl border transition-all cursor-pointer flex items-center gap-4 ${selectedReport?.id === report.id ? 'border-red-600 shadow-md ring-1 ring-red-500/10' : 'border-gray-100 shadow-sm hover:border-gray-300'}`}
              >
                <div className={`w-10 h-10 rounded-xl shrink-0 flex items-center justify-center font-black text-xs ${report.targetType === ReportTargetType.VULNERABLE ? 'bg-red-50 text-red-700' : 'bg-indigo-50 text-indigo-700'}`}>
                  {report.targetType === ReportTargetType.VULNERABLE ? 'V' : 'P'}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h4 className="text-xs font-black text-gray-900 truncate uppercase">{report.title}</h4>
                    {report.attachments && report.attachments.length > 0 && <Paperclip size={10} className="text-gray-400" />}
                  </div>
                  <p className="text-[9px] text-gray-400 font-medium truncate">{report.citizenName} • {new Date(report.createdAt).toLocaleDateString('vi-VN')}</p>
                </div>
                <ChevronRight size={16} className="text-gray-300" />
              </div>
            ))
          )}
        </div>
      </div>

      {selectedReport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-end md:items-center justify-center p-4" onClick={() => setSelectedReport(null)}>
          <div 
            className="bg-white w-full max-w-[440px] rounded-t-[3rem] md:rounded-[3rem] p-8 space-y-6 max-h-[85vh] overflow-y-auto animate-in slide-in-from-bottom duration-500 shadow-2xl"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-start border-b pb-4">
              <div className="space-y-1">
                <span className={`text-[9px] font-black uppercase tracking-[0.2em] px-2 py-0.5 rounded ${
                  selectedReport.status === ReportStatus.PENDING ? 'bg-amber-100 text-amber-700' :
                  selectedReport.status === ReportStatus.PROCESSING ? 'bg-blue-100 text-blue-700' :
                  selectedReport.status === ReportStatus.RESOLVED ? 'bg-green-100 text-green-700' :
                  'bg-red-100 text-red-700'
                }`}>
                  {selectedReport.status}
                </span>
                <h3 className="text-xl font-black text-gray-900 uppercase leading-tight mt-2">{selectedReport.title}</h3>
              </div>
              <button onClick={() => setSelectedReport(null)} className="p-2 bg-gray-50 rounded-full text-gray-400 hover:text-gray-900 transition-colors font-bold text-xl">×</button>
            </div>

            <div className="space-y-4">
              <div className="bg-red-50 p-4 rounded-2xl space-y-2 border border-red-100">
                <div className="flex items-center gap-2 text-[10px] font-black text-red-800 uppercase tracking-widest">
                  <MessageSquare size={14} /> AI Phân tích & Tóm tắt
                </div>
                <p className="text-[11px] text-red-900 leading-relaxed italic">
                  {selectedReport.aiSummary || "Đang phân tích..."}
                </p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Người gửi</p>
                  <p className="text-xs font-bold text-gray-800">{selectedReport.citizenName}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Điện thoại</p>
                  <p className="text-xs font-bold text-gray-800">{selectedReport.phoneNumber}</p>
                </div>
              </div>

              <div className="space-y-1">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Nội dung chi tiết</p>
                <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                  <p className="text-[11px] text-gray-600 leading-relaxed">{selectedReport.description}</p>
                </div>
              </div>

              <div className="space-y-2">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1">
                  <Paperclip size={12} /> Tài liệu chứng cứ ({selectedReport.attachments?.length || 0})
                </p>
                {selectedReport.attachments && selectedReport.attachments.length > 0 ? (
                  <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
                    {selectedReport.attachments.map((file, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 bg-white border border-gray-100 rounded-xl hover:border-red-100 transition-all">
                        <div className="shrink-0">{getFileIcon(file.type)}</div>
                        <div className="flex-1 min-w-0">
                          <p className="text-[10px] font-bold text-gray-700 truncate">{file.name}</p>
                          <p className="text-[8px] text-gray-400 font-mono uppercase">{formatFileSize(file.size)}</p>
                        </div>
                        <button 
                          onClick={() => downloadFile(file)}
                          className="p-2 bg-gray-50 rounded-lg text-gray-400 hover:text-red-700 transition-colors"
                        >
                          <Download size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-[10px] text-gray-400 italic px-2">Không có tài liệu đính kèm.</p>
                )}
              </div>

              <div className="flex flex-col gap-2 pt-4">
                <div className="flex gap-2">
                  <button 
                    onClick={() => handleUpdateStatus(selectedReport.id, ReportStatus.PROCESSING)}
                    disabled={selectedReport.status === ReportStatus.PROCESSING || selectedReport.status === ReportStatus.RESOLVED}
                    className={`flex-1 py-4 font-black rounded-2xl text-[10px] uppercase tracking-widest transition-all shadow-lg ${
                      selectedReport.status === ReportStatus.PROCESSING || selectedReport.status === ReportStatus.RESOLVED
                      ? 'bg-gray-100 text-gray-400 cursor-not-allowed shadow-none'
                      : 'bg-red-900 text-white shadow-red-100 hover:bg-red-800'
                    }`}
                  >
                    Tiếp nhận xử lý
                  </button>
                  <button 
                    onClick={() => handleUpdateStatus(selectedReport.id, ReportStatus.REJECTED)}
                    disabled={selectedReport.status === ReportStatus.RESOLVED}
                    className={`px-6 py-4 border font-black rounded-2xl text-[10px] uppercase tracking-widest transition-all ${
                      selectedReport.status === ReportStatus.REJECTED
                      ? 'bg-red-50 text-red-400 border-red-100'
                      : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'
                    }`}
                  >
                    Từ chối
                  </button>
                </div>

                {(selectedReport.status === ReportStatus.PROCESSING) && (
                  <button 
                    onClick={() => handleUpdateStatus(selectedReport.id, ReportStatus.RESOLVED)}
                    className="w-full py-4 bg-green-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-lg shadow-green-100 hover:bg-green-700 flex items-center justify-center gap-2"
                  >
                    <CheckCircle size={16} />
                    Đã giải quyết xong
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Report, ReportStatus } from '../types';
import { Clock, Search, Filter, ArrowRight, Paperclip, RefreshCcw } from 'lucide-react';
import { getAllReports } from '../services/storageService';

export const MyReports: React.FC = () => {
  const [reports, setReports] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    setLoading(true);
    try {
      const data = await getAllReports();
      setReports(data);
    } catch (error) {
      console.error("Lỗi:", error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: ReportStatus) => {
    switch (status) {
      case ReportStatus.PENDING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case ReportStatus.PROCESSING: return 'bg-blue-100 text-blue-700 border-blue-200';
      case ReportStatus.RESOLVED: return 'bg-green-100 text-green-700 border-green-200';
      case ReportStatus.REJECTED: return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <RefreshCcw className="animate-spin text-red-700" size={32} />
        <p className="text-xs font-black uppercase text-gray-400">Đang truy xuất lịch sử...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="pt-4 px-2">
        <h1 className="text-xl font-black text-gray-900 uppercase">Lịch sử phản ánh</h1>
        <p className="text-xs text-gray-500 font-medium">Lưu trữ trên bộ nhớ an toàn (IndexedDB)</p>
      </div>

      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
          <input 
            type="text" 
            placeholder="Tìm mã đơn..."
            className="pl-9 pr-4 py-2 bg-white border border-gray-100 rounded-xl focus:ring-2 focus:ring-red-500 outline-none text-xs w-full"
          />
        </div>
        <button className="p-2 bg-white border border-gray-100 rounded-xl hover:bg-gray-50">
          <Filter size={18} className="text-gray-500" />
        </button>
      </div>

      {reports.length === 0 ? (
        <div className="bg-white border-2 border-dashed rounded-[2rem] p-12 flex flex-col items-center justify-center space-y-4 text-center">
          <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center text-gray-300">
            <Clock size={24} />
          </div>
          <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Chưa có dữ liệu đơn phản ánh</p>
          <a href="#/report" className="text-red-700 font-black text-xs uppercase hover:underline underline-offset-4">Gửi đơn ngay →</a>
        </div>
      ) : (
        <div className="space-y-4">
          {reports.map((report) => (
            <div key={report.id} className="bg-white rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all overflow-hidden animate-in slide-in-from-bottom duration-300">
              <div className="p-4 space-y-3">
                <div className="flex items-center justify-between">
                  <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-tight border ${getStatusColor(report.status)}`}>
                    {report.status}
                  </span>
                  <div className="flex items-center gap-2">
                    {report.attachments && report.attachments.length > 0 && <Paperclip size={10} className="text-gray-400" />}
                    <span className="text-[9px] font-mono text-gray-400">#{report.id.toUpperCase()}</span>
                  </div>
                </div>

                <div>
                  <h3 className="text-sm font-black text-gray-900 line-clamp-1">{report.title}</h3>
                  <p className="text-[10px] text-gray-400 flex items-center gap-1 mt-0.5">
                    <Clock size={10} />
                    {new Date(report.createdAt).toLocaleDateString('vi-VN')} • {report.targetType}
                  </p>
                </div>

                <p className="text-[11px] text-gray-500 line-clamp-2 leading-relaxed">{report.description}</p>

                <div className="pt-3 border-t border-gray-50 flex justify-end">
                  <button className="flex items-center gap-1.5 text-red-700 font-black text-[10px] uppercase tracking-wider group">
                    Chi tiết
                    <ArrowRight size={14} className="group-hover:translate-x-1 transition-transform" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Send, CheckCircle2, User, FileText, AlertCircle, Info, Paperclip, X, File, Image as ImageIcon, Film } from 'lucide-react';
import { ReportTargetType, ReportStatus, VULNERABLE_GROUPS, PUBLIC_INTEREST_GROUPS, Report, Attachment } from '../types';
import { analyzeReport } from '../services/geminiService';
import { saveReport } from '../services/storageService';

export const ReportForm: React.FC = () => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [attachments, setAttachments] = useState<Attachment[]>([]);

  const [formData, setFormData] = useState<Partial<Report>>({
    targetType: ReportTargetType.VULNERABLE,
    reporterRole: 'Bản thân',
    subCategory: VULNERABLE_GROUPS[0],
    citizenName: '',
    birthYear: '',
    address: '',
    phoneNumber: '',
    email: '',
    title: '',
    description: '',
  });

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newAttachments: Attachment[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const base64 = await fileToBase64(file);
      newAttachments.push({
        name: file.name,
        type: file.type,
        size: file.size,
        data: base64
      });
    }
    setAttachments([...attachments, ...newAttachments]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const removeAttachment = (index: number) => {
    setAttachments(attachments.filter((_, i) => i !== index));
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (type: string) => {
    if (type.startsWith('image/')) return <ImageIcon size={16} className="text-blue-500" />;
    if (type.startsWith('video/')) return <Film size={16} className="text-purple-500" />;
    return <File size={16} className="text-gray-500" />;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const aiSummary = await analyzeReport(formData);

      const newReport: Report = {
        ...formData as any,
        id: Math.random().toString(36).substr(2, 9),
        status: ReportStatus.PENDING,
        createdAt: new Date().toISOString(),
        aiSummary: aiSummary,
        attachments: attachments,
      };

      // Lưu vào IndexedDB thay vì localStorage để hỗ trợ dung lượng lớn
      await saveReport(newReport);

      setSubmitted(true);
      setTimeout(() => navigate('/my-reports'), 2000);
    } catch (err) {
      console.error("Lỗi khi gửi phản ánh:", err);
      alert("Có lỗi xảy ra khi lưu dữ liệu. Tệp tin đính kèm có thể quá lớn so với bộ nhớ tạm của trình duyệt.");
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-6 text-center animate-in fade-in zoom-in duration-500">
        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center shadow-lg">
          <CheckCircle2 size={40} className="text-green-600" />
        </div>
        <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tight">Tiếp nhận thành công!</h2>
        <p className="text-sm text-gray-500 px-6">Thông tin phản ánh và tài liệu đính kèm đã được lưu trữ an toàn.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="text-center pt-4">
        <h1 className="text-xl font-black text-gray-900 uppercase tracking-widest">Nội dung phản ánh</h1>
        <div className="h-1 w-12 bg-red-600 mx-auto mt-2 rounded-full" />
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Step 1: Mục tiêu bảo vệ */}
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100 space-y-5">
          <h3 className="text-sm font-black flex items-center gap-2 text-red-800 uppercase tracking-wider">
            <Info size={18} /> Mục tiêu bảo vệ
          </h3>
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={() => setFormData({ ...formData, targetType: ReportTargetType.VULNERABLE, subCategory: VULNERABLE_GROUPS[0] })}
              className={`p-3 rounded-2xl border-2 text-center transition-all ${formData.targetType === ReportTargetType.VULNERABLE ? 'border-red-600 bg-red-50' : 'border-gray-50 bg-gray-50'}`}
            >
              <div className="font-bold text-[9px] text-gray-900 uppercase leading-tight">Nhóm dễ bị<br/>tổn thương</div>
            </button>
            <button
              type="button"
              onClick={() => setFormData({ ...formData, targetType: ReportTargetType.PUBLIC_INTEREST, subCategory: PUBLIC_INTEREST_GROUPS[0] })}
              className={`p-3 rounded-2xl border-2 text-center transition-all ${formData.targetType === ReportTargetType.PUBLIC_INTEREST ? 'border-indigo-600 bg-indigo-50' : 'border-gray-50 bg-gray-50'}`}
            >
              <div className="font-bold text-[9px] text-gray-900 uppercase leading-tight">Lợi ích<br/>công</div>
            </button>
          </div>
          <div className="space-y-2">
            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Danh mục chi tiết</label>
            <select 
              value={formData.subCategory}
              onChange={(e) => setFormData({...formData, subCategory: e.target.value})}
              className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-red-500 outline-none"
            >
              {formData.targetType === ReportTargetType.VULNERABLE 
                ? VULNERABLE_GROUPS.map(g => <option key={g} value={g}>{g}</option>)
                : PUBLIC_INTEREST_GROUPS.map(g => <option key={g} value={g}>{g}</option>)
              }
            </select>
          </div>
        </div>

        {/* Step 2: Người phản ánh */}
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100 space-y-5">
          <h3 className="text-sm font-black flex items-center gap-2 text-gray-800 uppercase tracking-wider">
            <User size={18} className="text-red-700" /> Người phản ánh
          </h3>
          <div className="space-y-4">
            <input required type="text" placeholder="Họ và tên" value={formData.citizenName} onChange={(e) => setFormData({...formData, citizenName: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-red-500 outline-none" />
            <div className="grid grid-cols-2 gap-4">
              <input required type="number" placeholder="Năm sinh" value={formData.birthYear} onChange={(e) => setFormData({...formData, birthYear: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-red-500 outline-none" />
              <input required type="tel" placeholder="SĐT liên hệ" value={formData.phoneNumber} onChange={(e) => setFormData({...formData, phoneNumber: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-red-500 outline-none" />
            </div>
            <input required type="text" placeholder="Địa chỉ thường trú" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-red-500 outline-none" />
          </div>
        </div>

        {/* Step 3: Nội dung */}
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100 space-y-5">
          <h3 className="text-sm font-black flex items-center gap-2 text-gray-800 uppercase tracking-wider">
            <FileText size={18} className="text-red-700" /> Chi tiết vụ việc
          </h3>
          <div className="space-y-4">
            <input required type="text" placeholder="Tiêu đề phản ánh" value={formData.title} onChange={(e) => setFormData({...formData, title: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-black focus:ring-2 focus:ring-red-500 outline-none" />
            <textarea required rows={5} placeholder="Mô tả chi tiết hành vi, thời gian, địa điểm..." value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-medium focus:ring-2 focus:ring-red-500 outline-none resize-none leading-relaxed" />
          </div>
        </div>

        {/* Step 4: Tài liệu đính kèm - KHÔNG BẮT BUỘC */}
        <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100 space-y-5">
          <div className="flex justify-between items-center">
            <h3 className="text-sm font-black flex items-center gap-2 text-gray-800 uppercase tracking-wider">
              <Paperclip size={18} className="text-red-700" /> Tài liệu chứng cứ
            </h3>
            <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest bg-gray-100 px-2 py-0.5 rounded-full">Không bắt buộc</span>
          </div>

          <div className="space-y-4">
            <input 
              type="file" 
              multiple 
              className="hidden" 
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="*/*"
            />
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="w-full py-6 border-2 border-dashed border-gray-200 rounded-[2rem] flex flex-col items-center justify-center gap-2 hover:border-red-300 hover:bg-red-50 transition-all text-gray-400 group"
            >
              <Paperclip size={32} className="group-hover:text-red-600 transition-colors" />
              <div className="text-center">
                <span className="text-[11px] font-black uppercase tracking-widest block text-gray-600">Nhấn để đính kèm chứng cứ</span>
                <span className="text-[9px] font-medium text-gray-400">Hỗ trợ Video, Hình ảnh, Tài liệu...</span>
              </div>
            </button>

            {attachments.length > 0 && (
              <div className="space-y-2 max-h-60 overflow-y-auto pr-1">
                {attachments.map((file, idx) => (
                  <div key={idx} className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl border border-gray-100 animate-in slide-in-from-left duration-200">
                    <div className="shrink-0">
                      {getFileIcon(file.type)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-[10px] font-bold text-gray-700 truncate">{file.name}</p>
                      <p className="text-[8px] text-gray-400 font-mono">{formatFileSize(file.size)}</p>
                    </div>
                    <button 
                      type="button" 
                      onClick={() => removeAttachment(idx)}
                      className="p-1 hover:bg-red-100 rounded-full text-gray-400 hover:text-red-600 transition-colors"
                    >
                      <X size={14} />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="p-4 bg-red-50 rounded-2xl flex gap-3 border border-red-100">
          <AlertCircle className="text-red-600 shrink-0" size={16} />
          <p className="text-[10px] text-red-800 leading-tight font-bold italic">
            Người phản ánh chịu trách nhiệm trước pháp luật về tính trung thực của chứng cứ và thông tin đã cung cấp.
          </p>
        </div>

        <button 
          disabled={loading}
          type="submit"
          className={`w-full py-5 bg-red-900 text-white font-black rounded-[2rem] shadow-xl hover:bg-red-800 transition-all flex items-center justify-center gap-2 tracking-widest uppercase text-sm ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
        >
          {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Send size={20} />}
          {loading ? 'Đang xử lý tài liệu...' : 'GỬI PHẢN ÁNH'}
        </button>
      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Report, ReportStatus, ReportTargetType, Attachment } from '../types';
import { Scale, Users, FileCheck, AlertTriangle, MessageSquare, Eye, PieChart, TrendingUp, Filter, ChevronRight, CheckCircle, Paperclip, File, Image as ImageIcon, Film, Download, RefreshCcw } from 'lucide-react';
import { getAllReports, updateReportStatus as dbUpdateStatus } from '../services/storageService';

export const AdminDashboard = () => {
  const [reports, setReports] = useState<Report[]>([]);
  const [selectedReport, setSelectedReport] = useState<Report | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    setLoading(true);
    try {
      const data = await getAllReports();
      setReports(data);
    } catch (error) {
      console.error("Lỗi khi tải dữ liệu:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (reportId: string, newStatus: ReportStatus) => {
    try {
      await dbUpdateStatus(reportId, newStatus);
      const updatedReports = reports.map(report => 
        report.id === reportId ? { ...report, status: newStatus } : report
      );
      setReports(updatedReports);

      if (selectedReport && selectedReport.id === reportId) {
        setSelectedReport({ ...selectedReport, status: newStatus });
      }
    } catch (error) {
      alert("Không thể cập nhật trạng thái đơn.");
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (type: string) => {
    if (type.startsWith('image/')) return <ImageIcon size={16} className="text-blue-500" />;
    if (type.startsWith('video/')) return <Film size={16} className="text-purple-500" />;
    return <File size={16} className="text-gray-500" />;
  };

  const downloadFile = (file: Attachment) => {
    const link = document.createElement('a');
    link.href = file.data;
    link.download = file.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const stats = [
    { label: 'Chờ tiếp nhận', count: reports.filter(r => r.status === ReportStatus.PENDING).length, color: 'text-amber-600', bg: 'bg-amber-50', icon: <AlertTriangle size={20} /> },
    { label: 'Đang xử lý', count: reports.filter(r => r.status === ReportStatus.PROCESSING).length, color: 'text-blue-600', bg: 'bg-blue-50', icon: <TrendingUp size={20} /> },
    { label: 'Đã giải quyết', count: reports.filter(r => r.status === ReportStatus.RESOLVED).length, color: 'text-green-600', bg: 'bg-green-50', icon: <FileCheck size={20} /> },
    { label: 'Từ chối', count: reports.filter(r => r.status === ReportStatus.REJECTED).length, color: 'text-red-600', bg: 'bg-red-50', icon: <Scale size={20} /> },
  ];

