        setSelectedReport({ 
          ...selectedReport, 
          status: newStatus, 
          resolutionResponse: newStatus === ReportStatus.RESOLVED ? resResponse : selectedReport.resolutionResponse,
          resolutionAttachments: newStatus === ReportStatus.RESOLVED ? resAttachments : selectedReport.resolutionAttachments
        });
